import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';

/**
 * MobileMenu — bouton hamburger + tiroir coulissant (mobile uniquement).
 * Ne change RIEN sur desktop. Réutilise la .elite-sidebar existante de chaque
 * dashboard en la transformant en tiroir via la classe body.menu-open.
 *
 * - Clic ☰ → ouvre le tiroir (la sidebar glisse depuis la gauche)
 * - Clic sur un élément de nav → ferme automatiquement (délégation)
 * - Clic sur le fond sombre ou la croix → ferme (retour)
 */
const MobileMenu = () => {
  const [open, setOpen] = useState(false);

  // Synchronise l'état avec une classe sur <body> (le CSS fait le reste)
  useEffect(() => {
    if (open) document.body.classList.add('menu-open');
    else document.body.classList.remove('menu-open');
    return () => document.body.classList.remove('menu-open');
  }, [open]);

  // Ferme le menu quand on clique sur un onglet de navigation
  useEffect(() => {
    if (!open) return;
    const onClick = (e) => {
      const btn = e.target.closest('.elite-nav button, .sidebar-footer .btn-logout, .user-pill-sidebar');
      if (btn) setOpen(false);
    };
    document.addEventListener('click', onClick, true);
    return () => document.removeEventListener('click', onClick, true);
  }, [open]);

  return (
    <>
      {/* Bouton hamburger flottant (visible seulement sur mobile via CSS) */}
      <button
        className="mobile-menu-btn"
        onClick={() => setOpen(v => !v)}
        aria-label="Menu"
      >
        {open ? <X size={22} /> : <Menu size={22} />}
      </button>

      {/* Fond sombre quand le menu est ouvert (clic = fermer = retour) */}
      {open && <div className="mobile-menu-backdrop" onClick={() => setOpen(false)} />}
    </>
  );
};

export default MobileMenu;
